const fs=require('node:fs'),vm=require('node:vm'),path=require('node:path'),assert=require('node:assert/strict');
const ROOT=path.resolve(__dirname,'..');
function make(name){
 const events={document:{},window:{},svg:{}};
 const eventTarget=(scope)=>({addEventListener(type,fn){(events[scope][type]??=[]).push(fn)}});
 const svg={...eventTarget('svg'),setPointerCapture(){},releasePointerCapture(){}};
 const ctx={console,Math,Set,Map,URLSearchParams,performance:{now:()=>0},window:eventTarget('window'),document:{...eventTarget('document'),hidden:false,getElementById:()=>svg,documentElement:{dataset:{}}},addEventListener(){},setTimeout,clearTimeout};
 vm.createContext(ctx);vm.runInContext(fs.readFileSync(path.join(ROOT,'dist/core.js'),'utf8'),ctx);vm.runInContext(fs.readFileSync(path.join(ROOT,'dist/elevator-occlusion.js'),'utf8'),ctx);vm.runInContext(fs.readFileSync(path.join(ROOT,`dist/scenes/${name}.js`),'utf8'),ctx);
 vm.runInContext(`globalThis.cfg=window.SCENES.${name}();cfg.state.pal=cfg.palette||'mustard';globalThis.draw=(yaw=45,pitch=35.264)=>{setCam(yaw,pitch);setLight(105);const text=cfg.scene(cfg.state,PALS[cfg.state.pal]);return cfg.scene.layers?cfg.scene.layers.map(p=>p.svg).join(''):text;};globalThis.layers=()=>cfg.scene.layers;globalThis.project=P;globalThis.setView=setCam;`,ctx);
 const steps=new Set(),messages=[];const ui={animate(fn){steps.add(fn)},invalidate(){},flash(text){messages.push(text)}};
 if(ctx.cfg.setup)ctx.cfg.setup(ui);
 const tick=(seconds,dt=1/60)=>{for(let t=0;t<seconds-1e-8;t+=dt)for(const f of [...steps])if(f(Math.min(dt,seconds-t))===false)steps.delete(f)};
 const click=label=>{const b=ctx.cfg.buttons.find(b=>b.label.startsWith(label));assert(b,`Missing ${name} button ${label}`);return b.onClick(ctx.cfg.state,ui)};
 const event=(scope,type,e={})=>{for(const f of events[scope][type]||[])f(e)};
 return {ctx,cfg:ctx.cfg,state:ctx.cfg.state,ui,steps,messages,tick,click,event};
}
async function snapshots(suffix='latest'){
 const sharp=require('sharp'),items=[];
 for(const name of ['musicbox','turntable','camera','elevator'])for(const yaw of [45,135,225,315]){
  const t=make(name);if(name==='camera')Object.assign(t.state,{phase:'ready',eject:1,develop:1});if(name==='turntable')Object.assign(t.state,{arm:1,lift:0,elapsed:14,cue:'down'});if(name==='elevator')Object.assign(t.state,{door:0.5});
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="600" viewBox="-95 -140 190 220"><rect x="-95" y="-140" width="190" height="220" fill="#f2efe7"/>${t.ctx.draw(yaw)}<text x="-88" y="72" font-size="7" font-family="sans-serif">${name} yaw ${yaw}</text></svg>`;
  const data=await sharp(Buffer.from(svg)).png().toBuffer();items.push({input:data,left:(items.length%4)*600,top:Math.floor(items.length/4)*600});
 }
 const file=path.join(__dirname,`audit-mechanics-four-${suffix}.png`);await sharp({create:{width:2400,height:2400,channels:3,background:'#f2efe7'}}).composite(items).png().toFile(file);console.log(file);
}
async function runTests(){
 const results=[];const test=(name,fn)=>{try{fn();results.push({name,ok:true})}catch(e){results.push({name,ok:false,error:e.message})}};
 test('elevator: queued call during manual close completes and releases the driver',()=>{const t=make('elevator');t.click('关门');t.tick(.3);t.click('前往三楼');t.tick(12);assert.equal(t.state.floor,3);assert.equal(t.state.phase,'idle');assert.equal(t.steps.size,0)});
 test('elevator: manual close after arrival releases driver',()=>{const t=make('elevator');t.click('前往二楼');t.tick(4.6);assert.equal(t.state.phase,'waiting');t.click('关门');t.tick(2);assert.equal(t.state.door,0);assert.equal(t.steps.size,0)});
 test('elevator: queued calls execute once in FIFO order',()=>{const t=make('elevator');t.click('前往三楼');t.click('前往二楼');t.click('前往三楼');t.tick(20);assert.equal(t.state.floor,2);assert.equal(t.state.trips,2);assert.equal(t.steps.size,0)});
 test('elevator: reset invalidates travel',()=>{const t=make('elevator');t.click('前往三楼');t.tick(2);t.click('回到一楼');t.tick(12);assert.equal(t.state.floor,1);assert.equal(t.state.trips,0);assert.equal(t.state.door,1);assert.equal(t.steps.size,0)});
 test('camera: full exposure, locks, collection and reload',()=>{const t=make('camera');t.click('按下快门');t.click('按下快门');t.click('切换风景');assert.equal(t.state.frames,4);assert.equal(t.state.scene,0);t.tick(6);assert.equal(t.state.phase,'ready');t.click('收藏照片');assert.equal(t.state.collected,1);t.click('切换风景');assert.equal(t.state.scene,1);t.click('装入相纸');assert.equal(t.state.frames,5);assert.equal(t.steps.size,0)});
 test('camera: reset during each animation phase prevents stale collection',()=>{for(const at of [.1,.7,2]){const t=make('camera');t.click('按下快门');t.tick(at);t.click('重新开始');t.tick(10);assert.equal(t.state.phase,'idle');assert.equal(t.state.frames,5);assert.equal(t.state.collected,0);assert.equal(t.steps.size,0)}});
 test('turntable: pause freezes record and progress',()=>{const t=make('turntable');t.click('移入唱臂');t.tick(1);t.click('移入唱臂');t.tick(1);t.click('播放');t.tick(2);t.click('播放');const elapsed=t.state.elapsed,angle=t.state.angle;t.tick(3);assert.equal(t.state.elapsed,elapsed);assert.equal(t.state.angle,angle);assert.equal(t.steps.size,0)});
 test('turntable: automatic return lifts before lateral sweep',()=>{const t=make('turntable');Object.assign(t.state,{arm:1,armTarget:1,lift:0,liftTarget:0,cue:'down',elapsed:35.99});t.click('播放');t.tick(.2);assert.equal(t.state.arm,1);assert(t.state.lift>0);t.tick(2);assert.equal(t.state.arm,0);assert.equal(t.state.cue,'rest');assert.equal(t.steps.size,0);t.click('移入唱臂');assert.equal(t.state.elapsed,0)});
 test('turntable: manual parking preserves current groove angle until the arm is at rest',()=>{const t=make('turntable');Object.assign(t.state,{arm:1,armTarget:1,lift:1,liftTarget:1,cue:'hover',elapsed:18});t.click('唱臂归位');assert.equal(t.state.elapsed,18);t.tick(.1);assert(t.state.arm<1&&t.state.arm>0);assert.equal(t.state.elapsed,18);t.tick(2);assert.equal(t.state.arm,0);assert.equal(t.state.elapsed,0);assert.equal(t.state.cue,'rest');assert.equal(t.steps.size,0)});
 test('turntable: reset cancels pending motion',()=>{const t=make('turntable');t.click('移入唱臂');t.tick(.2);t.click('重新开始');t.tick(3);assert.equal(t.state.arm,0);assert.equal(t.state.lift,1);assert.equal(t.steps.size,0)});
 test('musicbox: repeated winding uses one driver and winds down',()=>{const t=make('musicbox');for(let i=0;i<8;i++)t.click('摇动手柄');assert.equal(t.steps.size,1);t.tick(6);assert.equal(t.state.speed,0);assert.equal(t.state.energy,0);assert(t.state.notes>0);assert.equal(t.steps.size,0)});
 test('musicbox: lid toggles can reverse, and reset cancels old animation',()=>{const t=make('musicbox');t.click('开合');t.tick(.2);t.click('开合');t.tick(2);assert.equal(t.state.lid,1);t.click('摇动');t.click('重新开始');t.tick(6);assert.equal(t.state.notes,0);assert.equal(t.steps.size,0)});
 test('all scenes: finite geometry in twelve views and valid state endpoints',()=>{for(const name of ['musicbox','turntable','camera','elevator']){const t=make(name);for(const yaw of [0,45,90,135,180,225,270,315])for(const pitch of [6,35.264,78])for(const endpoint of [0,1]){if(name==='musicbox')t.state.lid=endpoint;if(name==='camera')Object.assign(t.state,{eject:endpoint,develop:endpoint});if(name==='elevator')Object.assign(t.state,{door:endpoint,pos:endpoint*66});if(name==='turntable')Object.assign(t.state,{arm:endpoint,lift:1-endpoint,elapsed:36*endpoint});const svg=t.ctx.draw(yaw,pitch);assert(!/NaN|Infinity|undefined/.test(svg),`${name} yaw${yaw} pitch${pitch} state${endpoint}`);assert(svg.length>300)}}});
 test('camera: rear lens is occluded, top shutter remains above deck, back print is blank',()=>{const t=make('camera');Object.assign(t.state,{phase:'ready',eject:1,develop:1});t.ctx.draw(225);const layers=t.ctx.layers(),index=k=>layers.findIndex(p=>p.key===k);assert(index('lens')<index('body'));assert(index('shutter')>index('top'));assert(index('photo')>index('top'));assert(!layers.find(p=>p.key==='photo').svg.includes('#b7d3d4'));t.ctx.draw(45);assert(t.ctx.layers().find(p=>p.key==='photo').svg.includes('#b7d3d4'))});
 test('elevator: near enclosing walls occlude cabin, far walls do not',()=>{const t=make('elevator');for(const yaw of [45,135,225,315]){t.ctx.draw(yaw);const keys=t.ctx.layers().map(p=>p.key);assert.equal(keys.indexOf('rear')>keys.indexOf('cabinback'),yaw===135||yaw===225);assert.equal(keys.indexOf('side')>keys.indexOf('cabinside'),yaw===225||yaw===315)}});
 test('elevator: translating door leaves retain physical width and cabin floor is level',()=>{for(const door of [0,.2,.5,.8,1]){const t=make('elevator');t.state.door=door;vm.runInContext("globalThis.boxes=[];const originalBox=box;box=(...args)=>{boxes.push(args.slice(0,6));return originalBox(...args)}",t.ctx);t.ctx.draw();const leaves=t.ctx.boxes.filter(b=>[37.8,38.5].includes(b[0]));assert.equal(leaves.length,4);for(const b of leaves){assert(Math.abs(b[4]-b[1]-6)<1e-6);assert(b[3]<40)}for(const b of t.ctx.boxes.filter(b=>b[0]===39.2))assert(b[3]<40);const floor=t.ctx.boxes.find(b=>b[0]===9&&b[1]===10&&b[3]===40);assert.equal(floor[5],8)}});
 test('musicbox: fully closed solid lid clears all pins and gear teeth',()=>{const t=make('musicbox');t.state.lid=0;vm.runInContext("globalThis.lids=[];const originalLoft=loft;loft=(A,B,...args)=>{if(A.length===4)lids.push([A,B]);return originalLoft(A,B,...args)}",t.ctx);t.ctx.draw();assert.equal(t.ctx.lids.length,1);const [A,B]=t.ctx.lids[0];assert.equal(Math.min(...A.map(p=>p[2])),34);assert.equal(Math.max(...B.map(p=>p[2])),37);assert.equal(Math.min(...A.map(p=>p[0])),3);assert.equal(Math.max(...A.map(p=>p[0])),65);assert(25+7+1+.6<34);assert(25+7.6+.35<34)});
 test('musicbox: physical click winds once and immediately reports playback',()=>{const t=make('musicbox');const e={button:0,pointerId:1,clientX:20,clientY:20,target:{closest:()=>({})},stopImmediatePropagation(){},preventDefault(){}};t.event('svg','pointerdown',e);t.event('svg','pointerup',e);assert.equal(t.state.energy,1);assert(t.cfg.readout(t.state).includes('正在演奏'));t.tick(1.5);assert(t.state.notes>0);assert.equal(t.steps.size,0)});
 test('musicbox: foreign pointer-up and reset cannot create or end the wrong crank gesture',()=>{const t=make('musicbox');const e=id=>({button:0,pointerId:id,clientX:0,clientY:0,target:{closest:()=>({})},stopImmediatePropagation(){},preventDefault(){}});t.event('svg','pointerdown',e(1));t.event('svg','pointerup',e(2));t.event('svg','pointermove',{...e(1),clientX:20});assert(t.state.energy>0);t.click('重新开始');t.event('svg','pointermove',{...e(1),clientX:40});t.event('svg','pointerup',e(1));assert.equal(t.state.energy,0)});
 test('elevator: deterministic mixed input maintains door-motion interlock and settles',()=>{const t=make('elevator');let seed=193;const rand=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};for(let i=0;i<150;i++){const label=['前往一楼','前往二楼','前往三楼','开门','关门'][Math.floor(rand()*5)];t.click(label);t.tick(rand()*.5);assert(t.state.pos>=0&&t.state.pos<=66);assert(t.state.door>=0&&t.state.door<=1);if(t.state.phase==='moving')assert.equal(t.state.door,0)}t.tick(40);assert.equal(t.state.phase,'idle');assert.equal(t.steps.size,0)});
 for(const name of ['musicbox','turntable']){
  try{const t=make(name),instances=[];let stopped=0;class Audio{constructor(){this.state='suspended';this.currentTime=0;this.pending=[];instances.push(this)}resume(){return new Promise(resolve=>this.pending.push(()=>{this.state='running';resolve()}))}close(){this.state='closed';return Promise.resolve()}createOscillator(){return {type:'',frequency:{value:0},connect(){},start(){},stop(at){if(at==null){stopped++;this.onended?.()}},onended:null}}createGain(){return {gain:{setValueAtTime(){},exponentialRampToValueAtTime(){}},connect(){},disconnect(){}}}}
   t.ctx.window.AudioContext=Audio;const pending=t.click('开启');t.click('开启');instances[0].pending.shift()();await pending;assert.equal(t.state.sound,false,'second toggle must cancel a pending enable');const resetPending=t.click('开启');t.click('重新开始');instances[0].pending.shift()();await resetPending;assert.equal(t.state.sound,false,'reset must cancel pending resume');const enable=t.click('开启');instances[0].pending.shift()();await enable;assert.equal(t.state.sound,true);if(name==='musicbox')t.click('摇动');else{t.click('移入');t.tick(1);t.click('移入');t.tick(1);t.click('播放')}t.tick(.6);t.ctx.document.hidden=true;t.event('document','visibilitychange');assert(stopped>0,'hidden page must stop active voices');assert.equal(name==='musicbox'?t.state.energy:t.state.playing,name==='musicbox'?0:false);t.ctx.document.hidden=false;t.event('window','pagehide');assert.equal(t.state.sound,false);assert.equal(instances[0].state,'closed');t.event('window','pageshow');const reopened=t.click('开启');assert.equal(instances.length,2);instances[1].pending.shift()();await reopened;assert.equal(t.state.sound,true);t.click('重新开始');t.tick(3);assert.equal(t.steps.size,0);results.push({name:name+': pending audio cancel, hidden silence, reset and BFCache re-enable',ok:true});
  }catch(e){results.push({name:name+': audio lifecycle',ok:false,error:e.stack})}
 }
 console.log(JSON.stringify(results,null,2));if(results.some(r=>!r.ok))process.exitCode=1;
}
if(require.main===module){if(process.argv[2]==='snapshots')snapshots(process.argv[3]).catch(e=>{console.error(e);process.exitCode=1});else runTests().catch(e=>{console.error(e);process.exitCode=1})}
module.exports={make,runTests,snapshots};
